def estimate_past_days(apps, schema_editor):
    """Mark staff present on past days where their work shows they were in.

    Only days before the person's first real shift are considered, so real
    attendance is never overlapped. The estimated day has no hours.
    """

    from collections import defaultdict

    from django.utils import timezone

    StaffProfile = apps.get_model("store", "StaffProfile")
    ShiftRecord = apps.get_model("store", "ShiftRecord")
    Order = apps.get_model("store", "Order")

    for profile in StaffProfile.objects.filter(role__in=["employee", "delivery"]):
        user_id = profile.user_id

        first_real = (
            ShiftRecord.objects.filter(user_id=user_id, is_estimated=False)
            .order_by("punched_in_at")
            .values_list("punched_in_at", flat=True)
            .first()
        )
        cutoff = timezone.localtime(first_real).date() if first_real else None

        # day -> {"first": earliest activity, "packed": n, "delivered": n}
        days = defaultdict(lambda: {"first": None, "packed": 0, "delivered": 0})

        def record(moment, kind):
            if moment is None:
                return
            day = timezone.localtime(moment).date()
            if cutoff and day >= cutoff:
                return
            entry = days[day]
            entry[kind] += 1
            if entry["first"] is None or moment < entry["first"]:
                entry["first"] = moment

        for packed_at in Order.objects.filter(assigned_to_id=user_id).values_list("packed_at", flat=True):
            record(packed_at, "packed")

        for delivered_at, shipped_at in Order.objects.filter(delivery_person_id=user_id).values_list(
            "delivered_at", "shipped_at"
        ):
            record(delivered_at or shipped_at, "delivered")

        for day, entry in days.items():
            work = []
            if entry["packed"]:
                work.append(f"packed {entry['packed']} order{'s' if entry['packed'] != 1 else ''}")
            if entry["delivered"]:
                work.append(f"delivered {entry['delivered']} order{'s' if entry['delivered'] != 1 else ''}")

            ShiftRecord.objects.create(
                user_id=user_id,
                role=profile.role,
                punched_in_at=entry["first"],
                punched_out_at=entry["first"],
                is_estimated=True,
                note="Estimated from work: " + ", ".join(work),
            )


